# Zugangsvoraussetzungen, Beantragung, Vertragszeitraum und Maßnahmenkombination.
package oepul.o6_16

import data.o6_16 as d

# --- Mindestteilnahme: 2,00 ha Ackerfläche in der Gebietskulisse im 1. Verpflichtungsjahr ---
min_area_first_year_met if gwa_arable_area_ha >= 2.0

access_violations contains v if {
	first_commitment_year
	not min_area_first_year_met
	v := {
		"rule_id": "O616-ACC-001",
		"message": sprintf("Im 1. Verpflichtungsjahr nur %v ha Ackerfläche in der Gebietskulisse (mind. 2,00 ha)", [gwa_arable_area_ha]),
	}
}

# --- Angebot nur in Burgenland, Kärnten, Niederösterreich, Oberösterreich, Steiermark, Wien ---
farm_state_offered if input.farm.region.federal_state in {s | some s in d.offered_federal_states}

access_violations contains v if {
	not farm_state_offered
	count(area_parcels) == 0
	v := {
		"rule_id": "O616-ACC-002",
		"message": "Betrieb bewirtschaftet keine Ackerflächen in den Angebotsbundesländern bzw. der Gebietskulisse",
	}
}

# --- Kombinationsverpflichtung: gleichzeitige Teilnahme an Maßnahme 6 oder 7 ---
combination_obligation_met if participates("6")

combination_obligation_met if participates("7")

access_violations contains v if {
	not combination_obligation_met
	v := {
		"rule_id": "O616-ACC-003",
		"message": "Keine zeitgleiche Teilnahme an „Begrünung von Ackerflächen – Zwischenfruchtanbau“ (6) oder „System Immergrün“ (7)",
	}
}

# --- Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (allgemeine Bedingung) ---
first_oepul_year if year == object.get(input, ["farm", "oepul", "first_oepul_participation_year"], null)

farm_min_size_met if object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= 0.5

farm_min_size_met if {
	agricultural := object.get(input, ["land", "total_area_ha"], 0)
	agricultural >= 1.5
}

access_violations contains v if {
	first_oepul_year
	not farm_min_size_met
	v := {
		"rule_id": "O616-GEN-003",
		"message": "Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (1,50 ha bzw. 0,50 ha geschützter Anbau) nicht erreicht",
	}
}

# --- Förderwerbende Personen ---
applicant := object.get(input, ["farm", "applicant"], {})

access_violations contains v if {
	object.get(applicant, "is_public_body", false) == true
	v := {
		"rule_id": "O616-GEN-001",
		"message": "Gebietskörperschaften und deren Einrichtungen sind in dieser Maßnahme keine förderwerbenden Personen",
	}
}

access_violations contains v if {
	object.get(applicant, "legal_form", "natural_person") in {"legal_person", "association"}
	object.get(applicant, "public_body_share_percent", 0) > 25
	v := {
		"rule_id": "O616-GEN-001",
		"message": "Beteiligung von Gebietskörperschaften über 25 % (bestimmender Einfluss)",
	}
}

access_violations contains v if {
	object.get(applicant, "active_farmer", true) == false
	v := {
		"rule_id": "O616-GEN-002",
		"message": "Förderwerbende Person ist kein aktiver Landwirt bzw. übt keine landwirtschaftliche Tätigkeit aus",
	}
}

# --- Beantragung: Maßnahmenantrag bis 31.12. vor Vertragsbeginn; letzter Einstieg 2025 ---
application_deadline(start_year) := sprintf("%d-12-31", [start_year - 1])

access_violations contains v if {
	start := commitment_start_year
	start != null
	app := object.get(o16, "measure_application_date", null)
	app != null
	app > application_deadline(start)
	v := {
		"rule_id": "O616-APP-001",
		"message": sprintf("Maßnahmenantrag %v nach Frist %v", [app, application_deadline(start)]),
	}
}

access_violations contains v if {
	start := commitment_start_year
	start != null
	start > 2025
	v := {
		"rule_id": "O616-APP-002",
		"message": "Letzter Einstieg in die Maßnahme ist mit Förderjahr 2025 (Beantragung bis 31.12.2024) möglich",
	}
}

# Vertragszeitraum: Beginn 2023/2024/2025, Ende jeweils 31.12.2028
contract_period := p if {
	some p in d.contract_periods
	date_year(p.start) == commitment_start_year
}

contract_end_date := "2028-12-31"

in_contract_period if {
	commitment_start_year != null
	year >= commitment_start_year
	year <= 2028
}

# --- Optionaler Zuschlag „Humusaufbau und Erosionsschutz in Wien“ ---
wien_option := object.get(o16, "wien_humus", {})

wien_option_applied if object.get(wien_option, "applied", false) == true

access_violations contains v if {
	wien_option_applied
	count(wien_area_parcels) == 0
	v := {
		"rule_id": "O616-WIEN-001",
		"message": "Zuschlag Wien nur für Betriebe mit Ackerflächen innerhalb der Gebietskulisse Wien",
	}
}

access_violations contains v if {
	wien_option_applied
	start := object.get(wien_option, "commitment_start_year", commitment_start_year)
	app := object.get(wien_option, "application_date", null)
	app != null
	app > application_deadline(start)
	v := {
		"rule_id": "O616-APP-001",
		"message": "Zuschlag Wien nicht fristgerecht im Maßnahmenantrag beantragt",
	}
}

access_violations contains v if {
	wien_option_applied
	object.get(wien_option, "commitment_start_year", commitment_start_year) > 2025
	v := {
		"rule_id": "O616-APP-002",
		"message": "Letzter Einstieg in den Zuschlag Wien ist mit Förderjahr 2025 möglich",
	}
}

access_violations contains v if {
	wien_option_applied
	object.get(wien_option, "scientific_project_confirmation", false) != true
	v := {
		"rule_id": "O616-WIEN-003",
		"message": "Teilnahmebestätigung der wissenschaftlichen Begleitung liegt nicht vor",
	}
}

# --- Optionaler Zuschlag „Stark stickstoffreduzierte Fütterung von Schweinen“ ---
pig_option := object.get(o16, "pig_feeding", {})

pig_option_applied if object.get(pig_option, "applied", false) == true

pig_groups := [g |
	some g in object.get(input, ["livestock", "species_groups"], [])
	g.species == "pigs"
]

gve_factor_for_pig_category(cat) := f if {
	key := d.pig_category_gve_mapping[cat]
	some r in d.annex_a_gve_key
	r.category_key == key
	f := r.gve_per_head
}

pig_group_gve(g) := g.gve if {
	g.gve != null
}

pig_group_gve(g) := gve if {
	object.get(g, "gve", null) == null
	n := object.get(g, "annual_average_count", g.animal_count)
	gve := n * gve_factor_for_pig_category(g.category)
}

pig_gve_total := sum([pig_group_gve(g) | some g in pig_groups])

pig_gve_per_ha_arable := pig_gve_total / total_arable_area_ha if total_arable_area_ha > 0

pig_density_met if pig_gve_per_ha_arable >= 1.0

access_violations contains v if {
	pig_option_applied
	not pig_density_met
	v := {
		"rule_id": "O616-PIG-001",
		"message": "Zuschlag Schweinefütterung: weniger als 1,00 GVE Schweine je ha Ackerfläche im Jahresdurchschnitt",
	}
}

access_violations contains v if {
	pig_option_applied
	start := object.get(pig_option, "start_year", year)
	app := object.get(pig_option, "application_date", null)
	app != null
	app > application_deadline(start)
	v := {
		"rule_id": "O616-APP-001",
		"message": "Zuschlag Schweinefütterung nicht fristgerecht im Maßnahmenantrag beantragt",
	}
}

access_violations contains v if {
	pig_option_applied
	object.get(pig_option, "start_year", year) > 2028
	v := {
		"rule_id": "O616-APP-003",
		"message": "Letzter Einstieg in den Zuschlag Schweinefütterung ist mit Förderjahr 2028 (Beantragung bis 31.12.2027) möglich",
	}
}

access_violations contains v if {
	pig_option_applied
	participates("9_pig_feeding")
	v := {
		"rule_id": "O616-PIG-002",
		"message": "Keine gleichzeitige Teilnahme an der Schweinefütterung in Maßnahme 16 und in Maßnahme 9 möglich",
	}
}

# Zuschlag Schweinefütterung verlängert sich automatisch, wenn er nicht abgemeldet wird
pig_option_auto_renewed if {
	pig_option_applied
	object.get(pig_option, "deregistered", false) == false
}

# --- Option AG und Zuschlag Cultan: jeweils mindestens ein Schlag ---
ag_parcels := [p | some p in parcels; is_ag_parcel(p)]

cul_parcels := [p | some p in parcels; is_cul_parcel(p)]

ag_option_participation if count(ag_parcels) > 0

cultan_participation if count(cul_parcels) > 0

access_violations contains v if {
	cultan_participation
	year < 2025
	v := {
		"rule_id": "O616-CUL-001",
		"message": "Zuschlag Cultan-Düngung erst ab Antragsjahr 2025",
	}
}

access_violations contains v if {
	some p in cul_parcels
	not parcel_in_area(p)
	v := {
		"rule_id": "O616-CUL-001",
		"parcel_id": p.parcel_id,
		"message": "CUL-Schlag liegt nicht in der Gebietskulisse gemäß Anhang G",
	}
}

default access_eligible := false

access_eligible if count(access_violations) == 0

# Allgemeine Teilnahmebedingungen (Informationsblatt Stand April 2026), SRL Allgemeiner Teil und GSP-AV, soweit
# für die Maßnahme 16 entscheidungs- oder berechnungsrelevant.
package oepul.o6_16

import data.o6_16 as d

# --- Flächenabgang: Toleranz 5 %, max. 5,00 ha, jedenfalls 0,50 ha pro Jahr ---
area_reduction_tolerance_ha(prev_area) := max_of(min_of(0.05 * prev_area, 5.0), 0.5)

area_reduction_ha := max_of(0, object.get(o16, "area_previous_year_ha", 0) - object.get(o16, "area_current_year_ha", object.get(o16, "area_previous_year_ha", 0)))

# Verlust der Verfügungsgewalt (Übertragung an anderen Betrieb) zählt nicht als rückzahlungspflichtige Verringerung
area_reduction_relevant_ha := max_of(0, area_reduction_ha - object.get(o16, "area_lost_disposal_right_ha", 0))

obligation_violations contains v if {
	area_reduction_relevant_ha > area_reduction_tolerance_ha(object.get(o16, "area_previous_year_ha", 0))
	v := {
		"rule_id": "O616-GEN-006",
		"message": sprintf("Flächenverringerung um %v ha über der Toleranz; Rückzahlung für die gesamte Differenzfläche", [area_reduction_relevant_ha]),
	}
}

repayment_area_ha := area_reduction_relevant_ha if {
	area_reduction_relevant_ha > area_reduction_tolerance_ha(object.get(o16, "area_previous_year_ha", 0))
}

# --- Mindestbewirtschaftung auf Ackerflächen: Ernte und Verbringen auf zumindest 85 % des Schlages ---
obligation_violations contains v if {
	some p in base_parcels
	not arable_forage_crop(p)
	share := object.get(p, ["operations", "harvested_share"], 1)
	share < 0.85
	not harvest_obligation_waived(p)
	not "OP" in parcel_codes(p)
	v := {
		"rule_id": "O616-GEN-004",
		"parcel_id": p.parcel_id,
		"message": "Ernte und Verbringen des Erntegutes auf weniger als 85 % des Schlages",
	}
}

# --- Verpflichtungsdauer ganzes Kalenderjahr: unterjährige Weitergabe nur bei Weiterführung durch Übernehmer ---
obligation_violations contains v if {
	some p in area_parcels
	object.get(p, "transferred_during_year", false) == true
	object.get(p, "successor_continues_commitment", false) != true
	not parcel_has_op_code(p)
	v := {
		"rule_id": "O616-GEN-005",
		"parcel_id": p.parcel_id,
		"message": "Unterjährig weitergegebene Fläche ohne Weiterführung durch den Übernehmer ist mit Code OP zu versehen",
	}
}

# --- Maßnahmenübernahme: bis 15.04. (2023 und 2028: 17.04.), Ausweitung max. 50 % ---
takeover_deadline(y) := sprintf("%d-04-17", [y]) if y in {2023, 2028}

takeover_deadline(y) := sprintf("%d-04-15", [y]) if not y in {2023, 2028}

takeover_allowed(t) if {
	t.date <= takeover_deadline(date_year(t.date))
	t.extension_to_other_area_ha <= 0.5 * t.taken_over_area_ha
	t.taker_previously_participating == false
}

# Zuschlag Schweinefütterung: Übernahme nur bei Betriebsauflösung, -teilung oder -zusammenlegung
takeover_allowed_pig_option(t) if {
	takeover_allowed(t)
	t.reason in {"farm_dissolution", "farm_division", "farm_merger"}
}

# --- Ausstieg vor Ende des Vertragszeitraums: Rückforderung aller Maßnahmenprämien ---
early_exit_repayment if {
	object.get(o16, "exit_year", null) != null
	o16.exit_year < 2028
	object.get(o16, "exit_due_to_revision_clause", false) != true
	object.get(o16, "exit_due_to_force_majeure", false) != true
}

# Abmeldung im laufenden Jahr: Maßnahme im betroffenen Förderjahr nicht mehr gültig
deregistration_invalidates_current_year(dereg_date) if date_year(dereg_date) == year

# --- Sanktionen bei Nichteinhaltung inhaltlicher Förderverpflichtungen (§ 48 GSP-AV) ---
sanction_percent(stage, y) := s.reduction_percent_until_2026 if {
	y <= 2026
	some s in d.sanction_stages
	s.stage == stage
}

sanction_percent(stage, y) := s.reduction_percent_from_2027 if {
	y >= 2027
	some s in d.sanction_stages
	s.stage == stage
}

# Wiederholter Verstoß gegen dieselbe Verpflichtung: Erhöhung um eine Stufe je Wiederholung (max. Stufe 7)
escalated_stage(base_stage, occurrence) := min_of(7, base_stage + (occurrence - 1))

# Kumulation mehrerer Verstöße, begrenzt mit 100 %
cumulated_sanction_percent(percents) := min_of(100, sum(percents))

# Zweimalige 100-%-Kürzung im Vertragszeitraum: Ausschluss und Rückforderung
exclusion_from_measure if count([s | some s in object.get(o16, "sanction_history_percent", []); s == 100]) >= 2

# --- Höhere Gewalt (§ 6 GSP-AV): Meldung binnen drei Wochen ab Möglichkeit ---
force_majeure_claim_timely(able_date, claim_date) if {
	delta := time.parse_ns("2006-01-02", claim_date) - time.parse_ns("2006-01-02", able_date)
	delta >= 0
	delta <= ((21 * 24) * 3600) * 1000000000
}

# --- Fristende an Wochenende/Feiertag (§ 5 GSP-AV); nicht für den Maßnahmenantrag (31.12.) ---
deadline_shift_excluded := {"measure_application", "catch_crop_variants_1_3", "catch_crop_variants_4_7", "slurry_quantity", "post_deadline_corrections"}

deadline_shift_applicable(deadline_kind) if not deadline_kind in deadline_shift_excluded

# --- Nationalparkflächen: keine Prämie, Verpflichtungen bleiben aufrecht ---
national_park_parcels := [p.parcel_id | some p in area_parcels; parcel_in_national_park(p)]

# Stickstoffbilanzierung, Übertrag auf die Folgekultur, Herbstbegrünung (Kapitel 4.3 Informationsblatt; SRL 2.16;
# NAPV Anlage 3 Abschnitte II–V; AMA-Hinweis vom 25.08.2026).
package oepul.o6_16

import data.o6_16 as d

nb(p) := object.get(p, "n_balance", {})

# --- Parameter je Antragsjahr der Folgekultur (bis 2024: > 10 kg/ha; ab 2025: > 20 kg/ha, max. 100 kg/ha) ---
n_params(y) := p if {
	some p in d.n_carryover_parameters
	y >= p.year_from
	y <= p.year_to
}

capped_surplus(s, params) := s if params.surplus_cap_kg_ha == null

capped_surplus(s, params) := min_of(s, params.surplus_cap_kg_ha) if params.surplus_cap_kg_ha != null

round2(x) := round(x * 100) / 100

# Anzurechnender Stickstoffübertrag (kg N/ha) aus dem Saldo der Vorkultur
n_carryover_kg_ha(surplus, app_year, _) := 0 if surplus <= n_params(app_year).surplus_threshold_kg_ha

n_carryover_kg_ha(surplus, app_year, factor) := c if {
	params := n_params(app_year)
	surplus > params.surplus_threshold_kg_ha
	c := round2(capped_surplus(surplus, params) * factor)
}

# Mindest-Reduktionsfaktor: 80 % (nördl./mittl. Burgenland, östl. NÖ inkl. Tullnerfeld, Wien), sonst 60 %
zone_factor(zone) := z.min_reduction_factor if {
	some z in d.n_reduction_zones
	z.zone == zone
}

parcel_reduction_factor(p) := 0.8 if parcel_area_state(p) == "Wien"

parcel_reduction_factor(p) := f if {
	parcel_area_state(p) != "Wien"
	f := zone_factor(object.get(p, "n_reduction_zone", "other"))
}

parcel_reduction_factor(p) := 0.6 if {
	parcel_area_state(p) != "Wien"
	not object.get(p, "n_reduction_zone", "other") in {z.zone | some z in d.n_reduction_zones}
}

# Ungenutzte Zwischenfrucht ohne Anlage gemäß Maßnahme 6/7: kein Reduktionsfaktor (voller Übertrag)
effective_factor(p) := 1.0 if {
	object.get(nb(p), "unused_catch_crop", false) == true
	object.get(nb(p), "catch_crop_per_measure_6_or_7", false) != true
}

effective_factor(p) := parcel_reduction_factor(p) if {
	not unused_catch_crop_without_measure(p)
}

unused_catch_crop_without_measure(p) if {
	object.get(nb(p), "unused_catch_crop", false) == true
	object.get(nb(p), "catch_crop_per_measure_6_or_7", false) != true
}

following_crop_year(p) := object.get(nb(p), "following_crop_application_year", year)

required_carryover(p) := n_carryover_kg_ha(s, following_crop_year(p), effective_factor(p)) if {
	s := object.get(nb(p), "previous_crop_n_saldo_kg_ha", null)
	s != null
}

obligation_violations contains v if {
	some p in area_parcels
	req := required_carryover(p)
	applied := object.get(nb(p), "following_crop_n_reduction_kg_ha", 0)
	applied < req
	v := {
		"rule_id": "O616-NB-001",
		"parcel_id": p.parcel_id,
		"message": sprintf("Düngung der Folgekultur um %v kg N/ha reduziert, erforderlich mind. %v kg N/ha", [applied, req]),
	}
}

# Reduktionsfaktor zwischen zwei Hauptkulturen nur einmal anwendbar
obligation_violations contains v if {
	some p in area_parcels
	object.get(nb(p), "reduction_factor_applications_between_main_crops", 0) > 1
	v := {
		"rule_id": "O616-NB-006",
		"parcel_id": p.parcel_id,
		"message": "Reduktionsfaktor zwischen zwei Hauptkulturen mehrfach angewendet",
	}
}

# Düngung ungenutzter Zwischenfrüchte: max. Düngebedarf der Folgekultur abzüglich Übertrag der Vorkultur
unused_catch_crop_max_n(p) := max_of(0, demand - carry) if {
	object.get(nb(p), "unused_catch_crop", false) == true
	demand := object.get(nb(p), "following_main_crop_n_demand_kg_ha", null)
	demand != null
	carry := object.get(nb(p), "carryover_after_factor_kg_ha", required_carryover_or_zero(p))
}

required_carryover_or_zero(p) := c if c := required_carryover(p)

required_carryover_or_zero(p) := 0 if not required_carryover(p)

obligation_violations contains v if {
	some p in area_parcels
	limit := unused_catch_crop_max_n(p)
	applied := object.get(nb(p), "unused_catch_crop_n_applied_kg_ha", 0)
	applied > limit
	v := {
		"rule_id": "O616-NB-007",
		"parcel_id": p.parcel_id,
		"message": sprintf("Ungenutzte Zwischenfrucht mit %v kg N/ha gedüngt, zulässig max. %v kg N/ha", [applied, limit]),
	}
}

# Auf ungenutzte Zwischenfrüchte ausgebrachter Stickstoff ist zur Gänze der Folgekultur anzurechnen
n_credit_to_following_main_crop(p) := required_carryover_or_zero(p) + object.get(nb(p), "unused_catch_crop_n_applied_kg_ha", 0)

# Gemüse mit Nmin-Analyse: Abzug mindestens in Höhe des Stickstoffsaldos der Vorkultur
vegetable_min_deduction(p) := max_of(nmin, saldo) if {
	nmin := object.get(nb(p), "vegetable_nmin_analysis_kg_ha", null)
	nmin != null
	saldo := object.get(nb(p), "previous_crop_n_saldo_kg_ha", 0)
	parcel_crop_name(p) in field_vegetable_set
	object.get(nb(p), "previous_crop_name", "") in field_vegetable_set
}

obligation_violations contains v if {
	some p in area_parcels
	req := vegetable_min_deduction(p)
	applied := object.get(nb(p), "vegetable_nmin_deduction_kg_ha", 0)
	applied < req
	v := {
		"rule_id": "O616-NB-009",
		"parcel_id": p.parcel_id,
		"message": sprintf("Nmin-Abzug %v kg N/ha geringer als Stickstoffsaldo der Vorkultur (%v kg N/ha)", [applied, req]),
	}
}

field_vegetable_set := {v | some v in d.field_vegetables}

pumpkin_crops := {"Kürbis", "Ölkürbis", "Speisekürbis"}

# --- Herbstbegrünung: Anlage einer Folgekultur bis 15.11. oder einer Zwischenfrucht gemäß Maßnahme 6/7 ---
autumn_cover_trigger(p) if object.get(nb(p), "previous_crop_n_saldo_kg_ha", 0) > 30

autumn_cover_trigger(p) if {
	p.area_ha > 0.3
	prev := object.get(nb(p), "previous_crop_name", "")
	prev in (field_vegetable_set | pumpkin_crops)
}

autumn_cover_trigger(p) if object.get(nb(p), "fallow_ploughed_before_nov15", false) == true

autumn_cover_trigger(p) if arable_forage_ploughed(p)

arable_forage_ploughed(p) if object.get(nb(p), "arable_forage_ploughed_before_nov15", false) == true

autumn_cover_exempt(p) if {
	object.get(nb(p), "previous_crop_harvested_after_sep30", false) == true
	not arable_forage_ploughed(p)
}

autumn_cover_established(p) if object.get(nb(p), "follow_crop_sown_by_nov15", false) == true

autumn_cover_established(p) if object.get(nb(p), "catch_crop_per_measure_6_or_7", false) == true

obligation_violations contains v if {
	some p in area_parcels
	autumn_cover_trigger(p)
	not autumn_cover_exempt(p)
	not autumn_cover_established(p)
	v := {
		"rule_id": "O616-NB-005",
		"parcel_id": p.parcel_id,
		"message": "Keine Folgekultur bis 15.11. bzw. keine Zwischenfrucht gemäß Maßnahme 6/7 angelegt",
	}
}

# --- Stickstoffsaldo innerhalb von 14 Tagen nach der Ernte berechnen; jährlicher Saldo bei mehrjährigen Kulturen ---
obligation_violations contains v if {
	some p in area_parcels
	delay := object.get(nb(p), "saldo_calculation_delay_days", 0)
	delay > 14
	v := {
		"rule_id": "O616-NB-010",
		"parcel_id": p.parcel_id,
		"message": "Stickstoffsaldo nicht innerhalb von 14 Tagen nach der Ernte berechnet",
	}
}

obligation_violations contains v if {
	some p in area_parcels
	object.get(nb(p), "perennial_crop", false) == true
	object.get(nb(p), "annual_saldo_calculated", true) == false
	v := {
		"rule_id": "O616-NB-008",
		"parcel_id": p.parcel_id,
		"message": "Bei mehrjährigen Kulturen ist jährlich ein Saldo zu bilden",
	}
}

# --- Schlagbezogener Stickstoffsaldo (NAPV Anlage 3 Abschnitt V Tabelle 3) ---
uptake_factor_record(crop, diff) := r if {
	some r in d.napv_anlage3_a5_uptake_factors
	r.crop == crop
	r.differentiation == diff
}

grid_key(x) := sprintf("%.1f", [x])

wheat_barley_uptake(column, protein, moisture) := val if {
	some r in d.napv_anlage3_a5_wheat_barley_uptake
	r.crude_protein_percent_dm == protein
	val := r[column][grid_key(moisture)]
	val != null
}

# Körnerleguminosen und Ackerfutter: Stickstoffbedarf statt ertragsabhängigem Entzugsfaktor
legume_n_demand(b) := object.get(b, "crop_n_demand_kg_ha", default_legume_demand(b))

default_legume_demand(b) := 60 if object.get(b, "legume_footnote1", false) == true

default_legume_demand(b) := 0 if object.get(b, "legume_footnote1", false) != true

crop_uptake_kg_ha(b) := legume_n_demand(b) if {
	r := uptake_factor_record(b.uptake_crop, object.get(b, "uptake_differentiation", null))
	r.is_grain_or_forage_legume
}

crop_uptake_kg_ha(b) := u if {
	r := uptake_factor_record(b.uptake_crop, object.get(b, "uptake_differentiation", null))
	not r.is_grain_or_forage_legume
	r.n_uptake_kg_per_t != null
	u := r.n_uptake_kg_per_t * b.harvest_t_ha
}

crop_uptake_kg_ha(b) := u if {
	b.uptake_crop == "Weizen"
	u := wheat_barley_uptake("wheat", b.crude_protein_percent_dm, b.grain_moisture_percent) * b.harvest_t_ha
}

crop_uptake_kg_ha(b) := u if {
	b.uptake_crop == "Braugerste"
	u := wheat_barley_uptake("brewing_barley", b.crude_protein_percent_dm, b.grain_moisture_percent) * b.harvest_t_ha
}

# N-Saldo = Vorfruchtwirkung + aktive Düngung (+ N aus Bewässerung) − Entzug durch Ernte
computed_n_saldo(p) := round2(supply - crop_uptake_kg_ha(b)) if {
	b := nb(p)
	supply := (object.get(b, "previous_crop_effect_kg_ha", 0) + object.get(b, "crop_n_applied_kg_ha", 0)) + object.get(b, "irrigation_n_kg_ha", 0)
}

# Stickstoffmenge durch Bewässerungswasser (NAPV Anlage 3 Abschnitt IV), abzuziehen ab 10 kg N/ha
irrigation_n_kg_ha(nitrate_mg_l, irrigation_mm) := round2(((nitrate_mg_l / 4.43) * irrigation_mm) / 100)

irrigation_n_relevant(nitrate_mg_l, irrigation_mm) if irrigation_n_kg_ha(nitrate_mg_l, irrigation_mm) >= 10

# Option „Bewirtschaftung auswaschungsgefährdeter Ackerflächen“ (Code AG; Kapitel 4.8, 5, 6 Informationsblatt; SRL 2.16).
package oepul.o6_16

import data.o6_16 as d

ag(p) := object.get(p, "ag_option", {})

ag_permitted_land_use_set := {r.land_use | some r in d.ag_permitted_land_uses}

ag_div_land_use_set := {r.land_use | some r in d.ag_permitted_land_uses; r.div_combinable}

ag_first_year(p) := object.get(ag(p), "first_declared_year", year)

# Anlagejahr ggf. betriebsübergreifend (lagegenaue Weiterführung durch Folgebetrieb)
ag_establishment_year(p) := object.get(ag(p), "previous_holder_establishment_year", ag_first_year(p))

ag_earliest_ploughing_date(p) := sprintf("%d-09-15", [ag_establishment_year(p) + 1])

ag_issue(p, "Ackerfläche nicht in der Gebietskulisse") if not parcel_in_area(p)

ag_issue(p, "durchschnittliche Ackerzahl über 40") if {
	object.get(p, "average_arable_index", null) != null
	p.average_arable_index > 40
}

ag_issue(p, "im Mehrfachantrag 2020 als Grünland beantragt") if object.get(p, "grassland_in_mfa_2020", false) == true

ag_issue(p, "begrünte Fläche im Rahmen von GLÖZ 4") if object.get(p, "gloez4_buffer_strip", false) == true

ag_issue(p, "stillgelegte Fläche im Rahmen von GLÖZ 8 (bis 2024)") if {
	year <= 2024
	object.get(p, "gloez8_fallow", false) == true
}

ag_issue(p, "unzulässige Schlagnutzungsart (Grünbrache, Futtergräser, Sonstiges Feldfutter, Wechselwiese)") if {
	not parcel_crop_name(p) in ag_permitted_land_use_set
}

ag_issue(p, "AG mit DIV nur als Grünbrache oder Sonstiges Feldfutter") if {
	"DIV" in parcel_codes(p)
	not parcel_crop_name(p) in ag_div_land_use_set
}

ag_issue(p, "AG mit DIV nur bei Teilnahme an UBB (1A) oder BIO (1B)") if {
	"DIV" in parcel_codes(p)
	not participates("1A")
	not participates("1B")
}

ag_issue_messages := [
	"Ackerfläche nicht in der Gebietskulisse",
	"durchschnittliche Ackerzahl über 40",
	"im Mehrfachantrag 2020 als Grünland beantragt",
	"begrünte Fläche im Rahmen von GLÖZ 4",
	"stillgelegte Fläche im Rahmen von GLÖZ 8 (bis 2024)",
	"unzulässige Schlagnutzungsart (Grünbrache, Futtergräser, Sonstiges Feldfutter, Wechselwiese)",
	"AG mit DIV nur als Grünbrache oder Sonstiges Feldfutter",
	"AG mit DIV nur bei Teilnahme an UBB (1A) oder BIO (1B)",
]

ag_issues contains v if {
	some p in ag_parcels
	some msg in ag_issue_messages
	ag_issue(p, msg)
	v := {"rule_id": "O616-AG-001", "parcel_id": p.parcel_id, "message": msg}
}

ag_parcel_has_issue(p) if {
	some msg in ag_issue_messages
	ag_issue(p, msg)
}

ag_parcel_eligible(p) if {
	is_ag_parcel(p)
	not ag_parcel_has_issue(p)
}

# AG + NPF bis einschließlich 2024: Anrechnung für GLÖZ 8, aber keine ÖPUL-Prämie
ag_npf_no_premium(p) if {
	year <= 2024
	is_ag_parcel(p)
	"NPF" in parcel_codes(p)
}

# --- Förderverpflichtungen ---
obligation_violations contains v if {
	some p in ag_parcels
	not ag_sowing_ok(p)
	v := {
		"rule_id": "O616-AG-002",
		"parcel_id": p.parcel_id,
		"message": "Keine Einsaat einer winterharten Begrünungsmischung ohne Leguminosen bis 15.05. und kein bestehender Grünbrache-/Ackerfutterbestand",
	}
}

ag_sowing_ok(p) if object.get(ag(p), "existing_stand_retained", false) == true

ag_sowing_ok(p) if {
	sow := object.get(ag(p), "sowing_date", null)
	sow != null
	sow <= sprintf("%d-05-15", [ag_first_year(p)])
	object.get(ag(p), "winter_hardy_mix", false) == true
	object.get(ag(p), "mix_contains_legumes", true) == false
}

obligation_violations contains v if {
	some p in ag_parcels
	pl := object.get(ag(p), "ploughing_date", null)
	pl != null
	pl < ag_earliest_ploughing_date(p)
	v := {
		"rule_id": "O616-AG-003",
		"parcel_id": p.parcel_id,
		"message": sprintf("Umbruch am %v vor dem frühestmöglichen Termin %v", [pl, ag_earliest_ploughing_date(p)]),
	}
}

obligation_violations contains v if {
	some p in ag_parcels
	object.get(ag(p), "fertilizer_or_psm_used", false) == true
	v := {
		"rule_id": "O616-AG-004",
		"parcel_id": p.parcel_id,
		"message": "Pflanzenschutz- oder Düngemitteleinsatz auf auswaschungsgefährdeter Ackerfläche",
	}
}

# Mahd oder Häckseln mind. 1 x jedes zweite Jahr
obligation_violations contains v if {
	some p in ag_parcels
	years := {y | some y in object.get(ag(p), "mowing_or_mulching_years", [])}
	year > ag_first_year(p)
	not year in years
	not (year - 1) in years
	v := {
		"rule_id": "O616-AG-005",
		"parcel_id": p.parcel_id,
		"message": "Keine Mahd bzw. kein Häckseln im laufenden oder vorangegangenen Jahr",
	}
}

obligation_violations contains v if {
	some p in ag_parcels
	some prohibited in ["grazing", "threshing"]
	object.get(ag(p), prohibited, false) == true
	v := {
		"rule_id": "O616-AG-006",
		"parcel_id": p.parcel_id,
		"message": sprintf("Unzulässige Nutzung auf AG-Fläche: %v", [prohibited]),
	}
}

obligation_violations contains v if {
	some p in ag_parcels
	object.get(ag(p), "cover_maintained", true) == false
	v := {
		"rule_id": "O616-AG-006",
		"parcel_id": p.parcel_id,
		"message": "Begrünung auf AG-Fläche nicht erhalten",
	}
}

# Umwandlung von AG-Flächen in „Naturschutz“ oder „Ergebnisorientierte Bewirtschaftung“ bis 31.12.2025
ag_conversion_allowed(target, application_date) if {
	target in {"18", "19"}
	application_date <= "2025-12-31"
}

# Prämienfähige AG-Fläche: max. 20 % der Ackerfläche des Betriebes
ag_eligible_area_ha := sum([p.area_ha | some p in ag_parcels; ag_parcel_eligible(p); not ag_npf_no_premium(p); not parcel_has_op_code(p)])

ag_premium_area_ha := min_of(ag_eligible_area_ha, 0.2 * total_arable_area_ha)

# Optionale Zuschläge: Humusaufbau und Erosionsschutz in Wien (4.9), stark stickstoffreduzierte Fütterung von
# Schweinen (4.10) und Cultan-Düngung (4.11).
package oepul.o6_16

import data.o6_16 as d

# --- Wien: keine wendende Bodenbearbeitung im Vertragszeitraum (ausgenommen nach Mais) ---
obligation_violations contains v if {
	wien_option_applied
	some p in wien_area_parcels
	object.get(p, ["operations", "tillage_type"], "unknown") == "plough"
	object.get(p, ["operations", "inversion_tillage_after_maize"], false) != true
	v := {
		"rule_id": "O616-WIEN-002",
		"parcel_id": p.parcel_id,
		"message": "Wendende Bodenbearbeitung im Gebiet Wien (nicht nach Mais) bei Zuschlag Humusaufbau und Erosionsschutz",
	}
}

obligation_violations contains v if {
	wien_option_applied
	object.get(wien_option, "project_data_provided_on_request", true) == false
	v := {
		"rule_id": "O616-WIEN-003",
		"message": "Daten zur Flächenbewirtschaftung bzw. Bodenproben nicht an die Projektbeauftragten übermittelt",
	}
}

# --- Schweinefütterung: Rohproteingrenzen je kg Ration (88 % TM) bei allen am Betrieb gehaltenen Schweinen ---
cp_limit(cat) := r if {
	some r in d.pig_crude_protein_limits
	r.category == cat
}

pig_group_cp_compliant(g) if {
	lim := cp_limit(g.category)
	lim.average_or_phase_alternative
	object.get(g, ["feeding", "mode"], "average") == "average"
	g.feeding.crude_protein_average_g_per_kg <= lim.average_max_g_per_kg_88dm
}

pig_group_cp_compliant(g) if {
	lim := cp_limit(g.category)
	lim.average_or_phase_alternative
	g.feeding.mode == "phase"
	g.feeding.crude_protein_max_g_per_kg <= lim.phase_max_g_per_kg_88dm
}

pig_group_cp_compliant(g) if {
	lim := cp_limit(g.category)
	not lim.average_or_phase_alternative
	lim.average_max_g_per_kg_88dm != null
	g.feeding.crude_protein_average_g_per_kg <= lim.average_max_g_per_kg_88dm
}

pig_group_cp_compliant(g) if {
	lim := cp_limit(g.category)
	not lim.average_or_phase_alternative
	lim.average_max_g_per_kg_88dm == null
	g.feeding.crude_protein_max_g_per_kg <= lim.phase_max_g_per_kg_88dm
}

obligation_violations contains v if {
	pig_option_applied
	some g in pig_groups
	not pig_group_cp_compliant(g)
	v := {
		"rule_id": "O616-PIG-003",
		"message": sprintf("Rohproteingrenze für Kategorie %v nicht eingehalten bzw. nicht belegt", [g.category]),
	}
}

obligation_violations contains v if {
	pig_option_applied
	object.get(doc16, "pig_feeding_recipes_documented", false) != true
	v := {
		"rule_id": "O616-PIG-004",
		"message": "Kein Nachweis der stark stickstoffreduzierten Fütterung über Rezepturen (Rohprotein je kg bei 88 % TM)",
	}
}

obligation_violations contains v if {
	pig_option_applied
	some g in pig_groups
	object.get(g, ["feeding", "mode"], "average") == "phase"
	object.get(doc16, "phase_feeding_plausible", false) != true
	v := {
		"rule_id": "O616-PIG-005",
		"message": "Phasenfütterung technisch nicht plausibel gemacht (z. B. Silobeschriftung, Fütterungstechnik)",
	}
}

# --- Cultan-Düngung: mind. eine Düngergabe als Ammoniumdepot per Injektion (Nagelradverfahren) ---
cultan_applications(p) := [a |
	some a in fertilizer_applications(p)
	object.get(a, "method", "") == "cultan_injection"
]

obligation_violations contains v if {
	some p in cul_parcels
	count(cultan_applications(p)) == 0
	v := {
		"rule_id": "O616-CUL-002",
		"parcel_id": p.parcel_id,
		"message": "Keine Düngergabe als Ammoniumdepot im Cultan-Nagelradverfahren",
	}
}

obligation_violations contains v if {
	some p in cul_parcels
	some a in cultan_applications(p)
	not cultan_record_complete(a)
	v := {
		"rule_id": "O616-CUL-003",
		"parcel_id": p.parcel_id,
		"message": "Schlagbezogene Aufzeichnung (Art, Menge, Zeitpunkt) der Cultan-Injektion unvollständig",
	}
}

cultan_record_complete(a) if {
	object.get(a, "fertilizer_type", null) != null
	object.get(a, "amount_kg_ha", null) != null
	object.get(a, "date", null) != null
}

obligation_violations contains v if {
	some p in cul_parcels
	some a in cultan_applications(p)
	object.get(a, "by_contractor", false) == true
	object.get(a, "contractor_invoice", false) != true
	v := {
		"rule_id": "O616-CUL-004",
		"parcel_id": p.parcel_id,
		"message": "Ausbringung durch betriebsfremde Geräte ohne Rechnung oder gleichwertigen Nachweis",
	}
}

# Pflanzenschutz (Kapitel 4.6) und zusätzliche Förderverpflichtungen in Oberösterreich (Kapitel 4.7).
package oepul.o6_16

import data.o6_16 as d

psm_applications(p) := object.get(p, ["operations", "psm_applications"], [])

fertilizer_applications(p) := object.get(p, ["operations", "fertilizer_applications"], [])

restricted_crop_set := {r.crop | some r in d.psm_restricted_crops}

bentazon_reauthorised := object.get(input, ["context", "bentazon_reauthorised"], false)

banned_substances := {s.substance | some s in d.psm_banned_active_substances; not s.conditional} | conditional_banned

conditional_banned := {"Bentazon"} if bentazon_reauthorised

conditional_banned := set() if not bentazon_reauthorised

# Wirkstoffverbot bei Sorghum, Sudangras, Mais (inkl. Zuckermais, Saatmaisvermehrung), Raps, Soja, Zuckerrübe
obligation_violations contains v if {
	some p in area_parcels
	parcel_crop_name(p) in restricted_crop_set
	some a in psm_applications(p)
	some s in a.active_substances
	s in banned_substances
	v := {
		"rule_id": "O616-PSM-001",
		"parcel_id": p.parcel_id,
		"message": sprintf("Wirkstoff %v auf %v in der Gebietskulisse eingesetzt", [s, parcel_crop_name(p)]),
	}
}

# Angabeverpflichtung PSMBIO/PSMCS bis einschließlich Antragsjahr 2025 (gebeiztes Saatgut = flächige Anwendung)
psm_code_required(p) := "PSMCS" if {
	some a in psm_applications(p)
	a.product_type == "chemical_synthetic"
}

psm_code_required(p) := "PSMBIO" if {
	count(psm_applications(p)) > 0
	every a in psm_applications(p) {
		a.product_type == "organic_approved"
	}
}

obligation_violations contains v if {
	year <= 2025
	some p in area_parcels
	code := psm_code_required(p)
	not psm_code_satisfied(p, code)
	v := {
		"rule_id": "O616-PSM-002",
		"parcel_id": p.parcel_id,
		"message": sprintf("Flächiger PSM-Einsatz ohne Code %v im Mehrfachantrag", [code]),
	}
}

psm_code_satisfied(p, code) if code in parcel_codes(p)

# Bei Einsatz von Bio- und chemisch-synthetischen Mitteln genügt PSMCS
psm_code_satisfied(p, "PSMBIO") if "PSMCS" in parcel_codes(p)

psm_coding_required_in_year if year <= 2025

# --- Oberösterreich: Ausbringungsverbot leichtlöslicher N-Dünger 15.10.–15.02. (Mais: bis 21.03.) ---
in_window_oct15_feb15(date) if month_day(date) >= "10-15"

in_window_oct15_feb15(date) if month_day(date) <= "02-15"

in_window_oct15_mar21(date) if month_day(date) >= "10-15"

in_window_oct15_mar21(date) if month_day(date) <= "03-21"

maize_crop(p) if parcel_crop_name(p) in {"Mais", "Körnermais", "Silomais", "Zuckermais", "Saatmaisvermehrung", "Corn-Cob-Mix"}

maize_crop(p) if object.get(p, ["crop", "crop_category"], "") == "maize"

arable_forage_crop(p) if parcel_crop_name(p) in {c | some c in d.arable_forage_crops}

obligation_violations contains v if {
	some p in upper_austria_area_parcels
	not arable_forage_crop(p)
	not maize_crop(p)
	some a in fertilizer_applications(p)
	object.get(a, "readily_soluble", false) == true
	in_window_oct15_feb15(a.date)
	v := {
		"rule_id": "O616-OOE-001",
		"parcel_id": p.parcel_id,
		"message": sprintf("Leichtlöslicher N-Dünger am %v im Verbotszeitraum 15.10.–15.02. (Oberösterreich)", [a.date]),
	}
}

obligation_violations contains v if {
	some p in upper_austria_area_parcels
	maize_crop(p)
	some a in fertilizer_applications(p)
	object.get(a, "readily_soluble", false) == true
	in_window_oct15_mar21(a.date)
	v := {
		"rule_id": "O616-OOE-001",
		"parcel_id": p.parcel_id,
		"message": sprintf("Leichtlöslicher N-Dünger am %v bei Mais im Verbotszeitraum 15.10.–21.03. (Oberösterreich)", [a.date]),
	}
}

# Gabenteilung: > 80 kg/ha Nitrat-, Ammonium- oder Carbamid-N je Gabe (nach Stall- und Lagerverlusten)
obligation_violations contains v if {
	some p in upper_austria_area_parcels
	some a in fertilizer_applications(p)
	object.get(a, "slow_release", false) != true
	readily_available_n(a) > 80
	v := {
		"rule_id": "O616-OOE-002",
		"parcel_id": p.parcel_id,
		"message": sprintf("Stickstoffgabe am %v mit %v kg/ha leicht verfügbarem N nicht geteilt (max. 80 kg/ha)", [a.date, readily_available_n(a)]),
	}
}

# Ammonium-N aus Wirtschaftsdüngern gemäß NAPV Anlage 2, sonst angegebener Wert
readily_available_n(a) := a.readily_available_n_kg_ha if a.readily_available_n_kg_ha != null

readily_available_n(a) := round2((a.total_n_after_losses_kg_ha * share) / 100) if {
	object.get(a, "readily_available_n_kg_ha", null) == null
	some r in d.napv_anlage2_ammonium_share
	r.fertilizer == a.fertilizer_type
	share := r.nh4_n_percent
}

# Variante 3 der Maßnahme „Zwischenfruchtanbau“ in Oberösterreich unzulässig
obligation_violations contains v if {
	some p in upper_austria_area_parcels
	object.get(p, ["operations", "cover_crop", "variant"], null) == 3
	v := {
		"rule_id": "O616-OOE-003",
		"parcel_id": p.parcel_id,
		"message": "Begrünungsvariante 3 innerhalb der Gebietskulisse Oberösterreich nicht zulässig",
	}
}

# Kontrollgang oder Warndienstmeldung vor jeder chemisch-synthetischen PSM-Maßnahme
obligation_violations contains v if {
	some p in upper_austria_area_parcels
	some a in psm_applications(p)
	a.product_type == "chemical_synthetic"
	object.get(a, "prior_field_inspection_documented", false) != true
	object.get(a, "warning_service_documented", false) != true
	v := {
		"rule_id": "O616-OOE-004",
		"parcel_id": p.parcel_id,
		"message": sprintf("Chemisch-synthetische PSM-Maßnahme am %v ohne dokumentierten Kontrollgang/Warndienst", [a.date]),
	}
}

# Betriebs- und schlagbezogene Aufzeichnungen (Kapitel 4.1, 4.2 Informationsblatt; SRL 2.16; NAPV § 8 Abs. 1, § 9 Abs. 6).
package oepul.o6_16

# --- Betriebliche Aufzeichnungen: Düngeplanung bis 28.02., Düngebilanzierung bis 31.01. des Folgejahres ---
fertilization_plan_deadline := sprintf("%d-02-28", [year])

fertilization_balance_deadline := sprintf("%d-01-31", [year + 1])

obligation_violations contains v if {
	plan := object.get(doc16, "fertilization_plan_date", null)
	not plan_on_time(plan)
	v := {
		"rule_id": "O616-REC-002",
		"message": sprintf("Voraussichtliche Düngeplanung nicht bis %v angelegt", [fertilization_plan_deadline]),
	}
}

plan_on_time(plan) if {
	plan != null
	plan <= fertilization_plan_deadline
}

obligation_violations contains v if {
	bal := object.get(doc16, "fertilization_balance_date", null)
	bal != null
	bal > fertilization_balance_deadline
	v := {
		"rule_id": "O616-REC-003",
		"message": sprintf("Betriebliche Düngebilanzierung nicht bis %v abgeschlossen", [fertilization_balance_deadline]),
	}
}

# Düngevorgaben der NAPV auf allen bewirtschafteten Flächen; Aufzeichnungen gemäß § 8 Abs. 1 NAPV
obligation_violations contains v if {
	object.get(doc16, "napv_fertilization_rules_complied", true) == false
	v := {
		"rule_id": "O616-REC-001",
		"message": "Düngevorgaben der Nitrat-Aktionsprogramm-Verordnung nicht auf allen Flächen eingehalten",
	}
}

obligation_violations contains v if {
	object.get(doc16, "farm_records_napv_8_1_complete", true) == false
	v := {
		"rule_id": "O616-REC-001",
		"message": "Betriebliche Aufzeichnungen gemäß § 8 Abs. 1 NAPV unvollständig",
	}
}

# --- Schlagbezogene Aufzeichnungen (§ 9 Abs. 6 NAPV) für Ackerflächen in der Gebietskulisse ---
crop_area_in_gwa(crop) := sum([p.area_ha | some p in area_parcels; parcel_crop_name(p) == crop])

# Keine schlagbezogenen Aufzeichnungen bei Kulturen mit max. 0,30 ha je Kultur
plot_records_required(p) if {
	parcel_in_area(p)
	crop_area_in_gwa(parcel_crop_name(p)) > 0.3
}

obligation_violations contains v if {
	some p in area_parcels
	plot_records_required(p)
	object.get(p, ["plot_records", "complete"], false) != true
	v := {
		"rule_id": "O616-REC-004",
		"parcel_id": p.parcel_id,
		"message": "Schlagbezogene Aufzeichnungen (Schlag, Düngemittel, Bewässerung, Anbau/Ernte, Erntemenge mit Wiegebelegen, N-Saldo) unvollständig",
	}
}

obligation_violations contains v if {
	count([p | some p in area_parcels; plot_records_required(p)]) > 0
	object.get(doc16, "plot_records_electronic", false) != true
	v := {
		"rule_id": "O616-REC-005",
		"message": "Schlagbezogene Aufzeichnungen sind elektronisch zu führen",
	}
}

obligation_violations contains v if {
	some p in area_parcels
	plot_records_required(p)
	delay := object.get(p, ["plot_records", "max_delay_days"], 0)
	delay > 14
	v := {
		"rule_id": "O616-REC-006",
		"parcel_id": p.parcel_id,
		"message": sprintf("Aufzeichnung erst %v Tage nach Ausbringung/Anbau/Bewässerung/Ernte (max. 14 Tage)", [delay]),
	}
}

obligation_violations contains v if {
	object.get(doc16, "plot_records_provided_on_request", true) == false
	v := {
		"rule_id": "O616-REC-007",
		"message": "Aufzeichnungen wurden dem BMLUK im Bedarfsfall nicht zur Verfügung gestellt",
	}
}

obligation_violations contains v if {
	object.get(doc16, "records_kept_on_farm", true) == false
	v := {
		"rule_id": "O616-N26-001",
		"message": "Aufzeichnungen sind am Betrieb aufzubewahren (Hinweis AMA 25.08.2026)",
	}
}

# Aufbewahrung förderrelevanter Unterlagen bei mehrjährigen INVEKOS-Maßnahmen: vier Jahre ab Ende des Vertragszeitraums
records_retention_until := "2032-12-31"

# Weiterbildung, Gewässerschutzkonzept und Bodenuntersuchung (Kapitel 4.4, 4.5, 4.9 Informationsblatt; SRL 2.16).
package oepul.o6_16

import data.o6_16 as d

one_off_deadline := "2026-12-31"

credit_start := "2022-01-01"

one_off_obligations_due if year >= 2026

training_courses := object.get(doc16, ["training", "courses"], [])

# Anrechenbar: Kurse ab 01.01.2022 bis 31.12.2026 eines anerkannten Bildungsanbieters, keine Doppelanrechnung
course_creditable(c) if {
	c.date >= credit_start
	c.date <= one_off_deadline
	object.get(c, "provider_recognized", false) == true
	object.get(c, "counted_for_other_commitment", false) != true
	object.get(c, "counted_for_other_farm", false) != true
	object.get(c, "attendee_role", "farm_manager") in {"applicant", "farm_manager", "involved_person"}
}

creditable_training_hours := sum([c.hours |
	some c in training_courses
	course_creditable(c)
	object.get(c, "wien_additional", false) != true
])

wien_additional_training_hours := sum([c.hours |
	some c in training_courses
	course_creditable(c)
	object.get(c, "wien_additional", false) == true
])

obligation_violations contains v if {
	one_off_obligations_due
	creditable_training_hours < 10
	v := {
		"rule_id": "O616-TRN-001",
		"message": sprintf("Nur %v anrechenbare Weiterbildungsstunden bis 31.12.2026 (mind. 10 Stunden)", [creditable_training_hours]),
	}
}

# Verlässt die geschulte Person vor dem 31.12.2026 den Betrieb, ist ein Kurs bis dahin nachzuholen
obligation_violations contains v if {
	left := object.get(doc16, ["training", "trained_person_left_date"], null)
	left != null
	left < one_off_deadline
	object.get(doc16, ["training", "replacement_course_completed"], false) != true
	one_off_obligations_due
	v := {
		"rule_id": "O616-TRN-004",
		"message": "Geschulte Person hat den Betrieb vor dem 31.12.2026 verlassen; Kurs wurde nicht nachgeholt",
	}
}

obligation_violations contains v if {
	object.get(doc16, ["training", "confirmation_submitted_on_request"], true) == false
	v := {
		"rule_id": "O616-TRN-005",
		"message": "Kursbesuchsbestätigung nach Aufforderung nicht an die AMA übermittelt",
	}
}

# Betriebsbezogenes Gewässerschutzkonzept einmalig bis 31.12.2026
obligation_violations contains v if {
	one_off_obligations_due
	not water_protection_concept_on_time
	v := {
		"rule_id": "O616-TRN-002",
		"message": "Betriebsbezogenes Gewässerschutzkonzept nicht bis 31.12.2026 erstellt",
	}
}

water_protection_concept_on_time if {
	c := object.get(doc16, "water_protection_concept_date", null)
	c != null
	c <= one_off_deadline
}

# Zuschlag Wien: zusätzlich 3 Stunden Bildung und Beratung bis 31.12.2026
obligation_violations contains v if {
	wien_option_applied
	one_off_obligations_due
	wien_additional_training_hours < 3
	v := {
		"rule_id": "O616-WIEN-004",
		"message": "Zuschlag Wien: zusätzliche 3 Stunden Bildung/Beratung (Bodenproben, Humusaufbau, pfluglose Bodenbearbeitung) fehlen",
	}
}

# --- Bodenuntersuchung: pro angefangene 5 ha Ackerfläche (MFA 2026) in der Gebietskulisse mind. 1 Probe ---
soil_basis_area_ha := object.get(o16, "gwa_arable_area_mfa_2026_ha", gwa_arable_area_ha)

soil_samples_required_for(area_ha) := ceil_div(area_ha, 5)

soil_samples_required := soil_samples_required_for(soil_basis_area_ha)

wien_basis_area_ha := object.get(o16, "wien_arable_area_mfa_2026_ha", wien_arable_area_ha)

# Zuschlag Wien: doppelt so viele Proben, d. h. mind. 2 Proben je angefangene 5 ha im Gebiet Wien
wien_soil_samples_required := 2 * soil_samples_required_for(wien_basis_area_ha)

soil_samples := object.get(doc16, "soil_samples", [])

required_parameters := {x | some x in d.soil_sample_parameters}

sample_creditable(s) if {
	s.sample_date >= credit_start
	s.lab_submission_date <= one_off_deadline
	object.get(s, "accredited_lab", false) == true
	params := {x | some x in object.get(s, "parameters", [])}
	count(required_parameters - params) == 0
	object.get(s, "n_parameter", "") in {"mineral_n", "mineralisable_n"}
	object.get(s, "method", "") in {"sgd", "euf"}
	object.get(s, "taken_over_with_parcel", false) != true
}

creditable_soil_samples := count([s | some s in soil_samples; sample_creditable(s)])

creditable_wien_soil_samples := count([s |
	some s in soil_samples
	sample_creditable(s)
	object.get(s, "in_wien_area", false) == true
])

obligation_violations contains v if {
	one_off_obligations_due
	creditable_soil_samples < soil_samples_required
	v := {
		"rule_id": "O616-SOIL-001",
		"message": sprintf("%v anrechenbare Bodenproben, erforderlich %v", [creditable_soil_samples, soil_samples_required]),
	}
}

obligation_violations contains v if {
	some s in soil_samples
	sample_creditable(s)
	object.get(s, "entered_in_invekos_gis", false) != true
	v := {
		"rule_id": "O616-SOIL-003",
		"message": sprintf("Ergebnis der Bodenprobe %v nicht im INVEKOS-GIS erfasst", [object.get(s, "sample_id", "?")]),
	}
}

obligation_violations contains v if {
	wien_option_applied
	creditable_wien_soil_samples < wien_soil_samples_required
	in_contract_period
	year == 2028
	v := {
		"rule_id": "O616-WIEN-005",
		"message": sprintf("Zuschlag Wien: %v Bodenproben im Gebiet Wien, erforderlich %v", [creditable_wien_soil_samples, wien_soil_samples_required]),
	}
}

